<?php
$settings=store_runtime_settings();$user=null;try{$user=current_user();}catch(Throwable){}
store_page_start(store_t('Track Order'),store_t('Secure guest order tracking.'),['store_name'=>(string)($settings['store_name']??store_runtime_name()),'user'=>$user,'settings'=>$settings,'robots'=>'noindex,nofollow']);
$label=static fn(string $value):string=>store_t(ucwords(str_replace('_',' ',trim($value))));
$deliveryLabel=static function(string $fulfillment,string $status=''):string {
  if($status==='cancelled')return 'Cancelled';
  return match($fulfillment){'preparing'=>'Preparing your order','shipped'=>'Shipped','out_for_delivery'=>'Out for delivery','fulfilled'=>'Delivered','returned'=>'Returned',default=>($status==='confirmed'?'Order confirmed':'Order received')};
};
?>
<section class="checkout-shell order-confirmation-shell guest-tracking-shell">
  <?php if($error!==''||!is_array($order)):?><div class="checkout-confirmation-card"><span><?=store_h(store_t('PRIVATE ORDER TRACKING'))?></span><h1><?=store_h(store_t('We couldn’t open that order.'))?></h1><p><?=store_h($error!==''?$error:store_t('This tracking link is unavailable.'))?></p><div class="checkout-confirmation-actions"><a class="store-primary-button" href="<?=store_h(route_url('support.php'))?>"><?=store_h(store_t('CONTACT SUPPORT'))?></a><a class="store-secondary-button" href="<?=store_h(route_url('perfumes.php'))?>"><?=store_h(store_t('CONTINUE SHOPPING'))?></a></div></div>
  <?php else:$address=json_decode((string)($order['shipping_address_json']??''),true);if(!is_array($address))$address=[];?>
  <div class="guest-order-track-card">
    <header><div><span><?=store_h(store_t('ORDER'))?></span><h1><?=store_h((string)$order['order_number'])?></h1><p><?=store_h(store_t('Placed'))?> <?=web_local_datetime($order['placed_at']??null,'—')?></p></div><div><small><?=store_h(store_t('TOTAL'))?></small><strong><?=store_h(store_money((float)$order['grand_total'],(string)$order['currency']))?></strong></div></header>
    <div class="guest-order-status-grid"><div><small><?=store_h(store_t('ORDER'))?></small><strong><?=store_h($label((string)$order['status']))?></strong></div><div><small><?=store_h(store_t('PAYMENT'))?></small><strong><?=store_h($label((string)$order['payment_status']))?></strong></div><div><small><?=store_h(store_t('DELIVERY'))?></small><strong><?=store_h(store_t($deliveryLabel((string)$order['fulfillment_status'],(string)$order['status'])))?></strong></div></div>
    <section class="guest-order-items"><h2><?=store_h(store_t('Order items'))?></h2><?php foreach($items as $item):$trackingImage=store_image_path($item['image_path']??'');?><article><div><?php if($trackingImage!==''):?><img data-store-image-fallback-source src="<?=store_h(url(store_image_variant_path($trackingImage,'sm')))?>" alt=""><div data-store-image-fallback hidden><?=store_media_placeholder(store_t('Product image unavailable'),'order-media-placeholder')?></div><?php else:?><?=store_media_placeholder(store_t('Product image unavailable'),'order-media-placeholder')?><?php endif;?></div><span><small><?=store_h((string)($item['brand_name']??''))?></small><strong><?=store_h((string)$item['product_name'])?></strong><em><?=store_h((string)($item['variant_label']??''))?> · <?=store_h(store_t('Qty'))?> <?=(int)$item['quantity']?></em></span><b><?=store_h(store_money((float)$item['line_total'],(string)$order['currency']))?></b></article><?php endforeach;?></section>
    <section class="guest-order-delivery"><div><small><?=store_h(store_t('DELIVERY TO'))?></small><strong><?=store_h((string)($address['address']??''))?></strong><span><?=store_h(trim(implode(', ',array_filter([(string)($address['building']??''),(string)($address['city']??''),(string)($address['governorate']??'')]))))?></span></div><div><small><?=store_h(store_t('CONTACT'))?></small><strong><?=store_h((string)$order['customer_name'])?></strong><span><?=store_h((string)$order['customer_phone'])?></span></div></section>
    <?php if($history):?><section class="guest-order-timeline"><h2><?=store_h(store_t('Delivery progress'))?></h2><?php foreach(array_reverse($history) as $entry):?><div><i></i><span><strong><?=store_h(store_t($deliveryLabel((string)($entry['fulfillment_status']??''),(string)($entry['status']??''))))?></strong><small><?=web_local_datetime($entry['created_at']??null,'—')?><?php if((string)($entry['payment_status']??'')==='paid'):?> · <?=store_h(store_t('Payment received'))?><?php endif;?></small></span></div><?php endforeach;?></section><?php endif;?>
    <footer><a class="store-primary-button" href="<?=store_h(route_url('support.php'))?>"><?=store_h(store_t('NEED HELP? CONTACT SUPPORT'))?></a></footer>
  </div><?php endif;?>
</section>
<?php store_page_end(); ?>
